// El Worker de Cloudflare envía tras CAPTURAR el pago: { pagoId, captureId, producto, email, importe }
// Ojo: en esta versión de n8n el webhook entrega { headers, params, query, body }.
const raw = ($json.body && typeof $json.body === 'object' && !Array.isArray($json.body)) ? $json.body : $json;
const email = String(raw.email || raw.Email_Comprador || '').trim();
const productoRaw = raw.producto || raw.Nombre_Producto || '';
const producto = typeof productoRaw === 'string' ? productoRaw.trim() : String(productoRaw || '').trim();
const pagoId = String(raw.pagoId || raw.id || raw.paymentId || raw.resource_id || '').trim();
const captureId = String(raw.captureId || '').trim();
const importe = raw.importe ? String(raw.importe) : '';
if (!email || !producto || !pagoId) {
  throw new Error('Faltan datos del pedido (email, producto o pagoId)');
}
return [{ email, producto, pagoId, captureId, importe }];

const origen = $json;
const headers = { 'Authorization': 'Bearer ' + origen.access_token, 'Accept': 'application/json' };
try {
  const res = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://api-m.paypal.com/v2/checkout/orders/' + origen.pagoId,
    headers,
    json: true
  });
  return [{ json: { ...origen, ...res } }];
} catch (err) {
  return [{ json: { ...origen, status: 'NOT_FOUND', _verificar_error: String(err.message || err).slice(0, 200) } }];
}

// Solo se considera válido si la orden está COMPLETED y además la
// captura está COMPLETED (significa que el dinero ya se cobró).
// NUNCA enviar la clave por estado APPROVED (aún no se ha cobrado).
const estado = String($json.status || '');
const pu = ($json.purchase_units && $json.purchase_units[0]) || {};
const caps = (pu.payments && pu.payments.captures) || [];
const c = caps[0] || null;
const capOk = !!(c && c.status === 'COMPLETED');
const valido = estado === 'COMPLETED' && capOk;
const captureId = c ? String(c.id || '') : String($json.captureId || '');
return [{ ...$json, _paypal_valido: valido, _paypal_estado: estado, _capture_id: captureId }];

