const n = $('Normalizar pedido').item.json;
const url = 'https://nagokeys.com/api/keys?producto=' + encodeURIComponent(n.producto || '');
const res = await this.helpers.httpRequest({
  method: 'GET',
  url,
  headers: { 'x-nagokeys-api-key': 'REEMPLAZADA_API_KEY_NAGOKEYS', 'Accept': 'application/json' },
  json: true
});
return [{ json: res }];

// El GET /api/keys devuelve { ok, keys: [...] }.
// Tomamos la primera 'Disponible' y marcamos si hay stock o no.
const r = $json;
const keys = Array.isArray(r.keys) ? r.keys : [];
const disponibles = keys.filter(k => k && String(k.Estado).toLowerCase() === 'disponible');
if (!disponibles.length) {
  return [{ ...$json, _hay_clave: false }];
}
const k = disponibles[0];
return [{ ...$json, _hay_clave: true, _clave_id: k.id, _clave: k.Clave_Activacion }];

