const n = $('Normalizar pedido').item.json;
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://nagokeys.com/api/keys/vender',
  headers: { 'x-nagokeys-api-key': 'REEMPLAZADA_API_KEY_NAGOKEYS', 'Accept': 'application/json', 'Content-Type': 'application/json' },
  body: { id: Number($json._clave_id), email: n.email },
  json: true
});
return [{ json: res }];

const b64 = 'COLOCA_AQUI_TOKEN_BASIC_PAYPAL_LIVE';
const res = await this.helpers.httpRequest({
  method: 'POST',
  url: 'https://api-m.paypal.com/v1/oauth2/token',
  headers: { 'Authorization': 'Basic ' + b64, 'Content-Type': 'application/x-www-form-urlencoded', 'Accept': 'application/json' },
  body: 'grant_type=client_credentials',
  json: true
});
return [{ json: { pagoId: $json.pagoId, producto: $json.producto, email: $json.email, captureId: $json.captureId, importe: $json.importe, access_token: res.access_token, token_type: res.token_type, expires_in: res.expires_in } }];
